        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
        Class<?>[] resolvedTypes = new Class<?>[actualTypeArguments.length];

        for (int i = 0; i < actualTypeArguments.length; i++) {
            Type type = actualTypeArguments[i];

            if (type instanceof Class) {
                resolvedTypes[i] = (Class<?>) type;
            } else if (type instanceof ParameterizedType) {
                resolvedTypes[i] = resolveParameterizedType_arguments((ParameterizedType) type, targetType)[0];
            } else if (type instanceof GenericArrayType) {
                GenericArrayType genericArrayType = (GenericArrayType) type;
                Type componentType = genericArrayType.getGenericComponentType();
                if (componentType instanceof Class) {
                    resolvedTypes[i] = Array.newInstance((Class<?>) componentType, 0).getClass();
                }
            } else {
                return null;
            }
        }

        return resolvedTypes;
    }

    return null;
}

