import org.elasticsearch.cluster.metadata.Mappings;

public Mappings diffStructure(String tableName, Mappings mappings) {
    // Extract the current index mappings
    Mappings currentIndexMappings = mappings;

    // Define the fields to exclude (e.g., _source)
    Set<String> fieldsToExclude = new HashSet<>();
    fieldsToExclude.add("_source");

    // Create a new Mappings object to store the differences
    Mappings resultingMappings = new Mappings.Builder();

    // Iterate over the current index mappings and add fields that are not in the input mappings
    for (Map.Entry<String, Object> entry : currentIndexMappings.getSourceAsMap().entrySet()) {
        String fieldName = entry.getKey();
        if (!fieldsToExclude.contains(fieldName)) {
            resultingMappings.source.put(fieldName, entry.getValue());
        }
    }

    return resultingMappings;
}
