protected List<TimeRange> buildTimeRanges(long start, long end) {
    long fetchDataDuration = 60000; // Example duration in milliseconds
    List<TimeRange> timeRanges = new ArrayList<>();

    if (start + fetchDataDuration > end) {
        timeRanges.add(new TimeRange(start, end));
    } else {
        long currentTime = start;
        while (currentTime < end) {
            long nextTime = Math.min(currentTime + fetchDataDuration, end);
            timeRanges.add(new TimeRange(currentTime, nextTime));
            currentTime = nextTime;
        }
    }

    return timeRanges;
}
