public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    try {
        Path path = Paths.get(u);
        String[] parts = path.getNameCount() > 0 ? path.getName(0).toString().split("/(?=[^/]*[!$&'()*+,;=])") : new String[0];
        for (String part : parts) {
            if (decode) {
                segments.add(new PathSegmentImpl(java.net.URLDecoder.decode(part, "UTF-8")));
            } else {
                segments.add(new PathSegmentImpl(part));
            }
        }
    } catch (URISyntaxException e) {
        // Handle the exception as appropriate, e.g., log it or throw a custom exception
    }
    return segments;
}
