public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder sb = new StringBuilder();
    boolean nextCharIsEscape = false;

    for (char c : str.toCharArray()) {
        if (nextCharIsEscape) {
            switch (c) {
                case 'b':
                    sb.append('\b');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '\"':
                    sb.append('"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                default:
                    throw new Exception("Unknown escape character: " + c);
            }
            nextCharIsEscape = false;
        } else {
            if (c == '\\') {
                nextCharIsEscape = true;
            } else {
                sb.append(c);
            }
        }
    }

    return sb.toString();
}

