private void ensureCapacity(int bytesNeeded) {
    if (this.cursor + bytesNeeded > this.data.length) {
        byte[] oldData = this.data;
        this.data = new byte[oldData.length + Math.max(oldData.length >> 1, bytesNeeded)];
        System.arraycopy(oldData, 0, this.data, 0, this.cursor);
    }
}
