private List<Integer> computeLowerBounds(List<K> keys) {
    if (keys == null || keys.isEmpty()) {
        return Collections.emptyList();
    }

    List<Integer> lowerBounds = new ArrayList<>();
    for (K key : keys) {
        if (key instanceof Comparable) {
            K minKey = key;
            for (K otherKey : keys) {
                if (otherKey != key && ((Comparable<K>) otherKey).compareTo(key) < 0) {
                    if (otherKey instanceof Comparable && ((Comparable<K>) otherKey).compareTo(minKey) < 0) {
                        minKey = otherKey;
                    }
                }
            }
            lowerBounds.add(minKey.hashCode());
        } else {
            throw new IllegalArgumentException("All keys must be Comparable");
        }
    }
    return lowerBounds;
}
