private List<Integer> computeUpperBounds(List<K> keys) {
    if (keys == null || keys.isEmpty()) {
        throw new IllegalArgumentException("Keys list cannot be null or empty");
    }

    List<Integer> upperBounds = new ArrayList<>();
    for (K key : keys) {
        if (key instanceof Comparable) {
            Comparator<K> comparator = (Comparator<K>) Comparator.reverseOrder();
            Optional<K> maxKey = keys.stream().max(comparator);
            if (maxKey.isPresent()) {
                upperBounds.add((Integer) maxKey.get());
            }
        } else {
            throw new UnsupportedOperationException("Key type must implement Comparable");
        }
    }

    return upperBounds;
}
